	@TestFactory
	Stream<DynamicTest> rejectsMalformedUtf8InCommentsAndVersionStrings() {
		List<String[]> contexts = List.of(
				new String[] { "full-line-comment", "#", "\n" + QUAD },
				new String[] { "trailing-comment", "<urn:s> <urn:p> <urn:o> . #", "\n" },
				new String[] { "version-string", "VERSION \"", "\"\n" + QUAD },
				new String[] { "version-comment", "VERSION \"1.2\"#", "\n" + QUAD });
		byte[][] malformed = {
				{ (byte) 0x80 },
				{ (byte) 0xC0, (byte) 0xAF },
				{ (byte) 0xED, (byte) 0xA0, (byte) 0x80 },
				{ (byte) 0xF4, (byte) 0x90, (byte) 0x80, (byte) 0x80 },
				{ (byte) 0xE2, (byte) 0x82 }
		};
		List<DynamicTest> tests = new ArrayList<>();
		for (String[] context : contexts) {
			byte[] prefix = context[1].getBytes(UTF_8);
			byte[] suffix = context[2].getBytes(UTF_8);
			for (byte[] invalid : malformed) {
				byte[] bytes = Arrays.copyOf(prefix, prefix.length + invalid.length + suffix.length);
				System.arraycopy(invalid, 0, bytes, prefix.length, invalid.length);
				System.arraycopy(suffix, 0, bytes, prefix.length + invalid.length, suffix.length);
				for (Mode mode : Mode.values()) {
					tests.add(DynamicTest.dynamicTest(mode + "/" + context[0] + "/" + HexFormat.of().formatHex(invalid),
							() -> {
								RDFParseException failure = assertThrows(RDFParseException.class,
										() -> parseRaw(bytes, mode));
								assertEquals(1L, failure.getLineNumber());
							}));
				}
			}
		}
		return tests.stream();
	}

