	private static Stream<DynamicTest> officialSyntax(String resourcePrefix, int expectedCases) throws IOException {
		String base = "https://example.test/fixtures/";
		Model manifest;
		try (InputStream input = resource(resourcePrefix + "manifest.ttl")) {
			manifest = Rio.parse(input, base, RDFFormat.TURTLE);
		}
		IRI action = VF.createIRI(MANIFEST_NS, "action");
		IRI positive = VF.createIRI(RDF_TEST_NS, "TestNQuadsPositiveSyntax");
		IRI negative = VF.createIRI(RDF_TEST_NS, "TestNQuadsNegativeSyntax");
		List<DynamicTest> tests = new ArrayList<>();
		for (Statement test : manifest.filter(null, RDF.TYPE, null)) {
			boolean valid = test.getObject().equals(positive);
			if (!valid && !test.getObject().equals(negative)) {
				continue;
			}
			String actionIri = manifest.filter(test.getSubject(), action, null)
					.objects()
					.iterator()
					.next()
					.stringValue();
			String filename = actionIri.substring(actionIri.lastIndexOf('/') + 1);
			byte[] bytes;
			try (InputStream input = resource(resourcePrefix + filename)) {
				bytes = input.readAllBytes();
			}
			for (Mode mode : Mode.values()) {
				tests.add(DynamicTest.dynamicTest(mode + "/" + (valid ? "positive/" : "negative/") + filename, () -> {
					if (valid) {
						parseRaw(bytes, mode);
					} else {
						assertThrows(RDFParseException.class, () -> parseRaw(bytes, mode), filename);
					}
				}));
			}
		}
		assertEquals(expectedCases * Mode.values().length, tests.size(), "manifest coverage");
		return tests.stream();
	}

	private static InputStream resource(String name) throws IOException {
		InputStream input = FastNQuadsRdf12ConformanceTest.class.getResourceAsStream(name);
		if (input != null) {
			return input;
		}
		throw new IOException("Missing audit fixture " + name);
	}

	@Test
	void preservesValuesAcrossEveryReadBoundary() throws IOException {
		String input = "\uFEFF# header\r\n"
				+ "_:same <urn:p> \"a\\nb😀\"@en--ltr _:graph .\r\n"
				+ "_:same <urn:p> <<( _:same <urn:p> \"\\u005Cn\" )>> _:graph .\r"
				+ "<urn:s> <urn:p> <urn:o> .";
		byte[] bytes = input.getBytes(UTF_8);
		List<Statement> expectedStatements = List.of(
				VF.createStatement(VF.createBNode("same"), P,
						VF.createLiteral("a\nb😀", "en", Literal.BaseDirection.LTR),
						VF.createBNode("graph")),
				VF.createStatement(VF.createBNode("same"), P,
						VF.createTripleTerm(VF.createBNode("same"), P, VF.createLiteral("\\n")),
						VF.createBNode("graph")),
				VF.createStatement(S, P, O));
		List<byte[][]> expected = expectedStatements.stream()
				.map(statement -> new byte[][] { CanonicalTermCodec.encode(statement.getSubject()),
						CanonicalTermCodec.encode(statement.getPredicate()),
						CanonicalTermCodec.encode(statement.getObject()),
						statement.getContext() == null ? null : CanonicalTermCodec.encode(statement.getContext()) })
				.toList();
		for (int split = 1; split < bytes.length; split++) {
			final int boundary = split;
			BufferedInputStream inputStream = new BufferedInputStream(new ByteArrayInputStream(bytes)) {
				private int consumed;

				@Override
				public synchronized int read(byte[] target, int offset, int length) throws IOException {
					int limit = consumed < boundary ? Math.min(length, boundary - consumed) : length;
					int count = super.read(target, offset, limit);
					if (count > 0) {
						consumed += count;
					}
					return count;
				}
			};
			List<byte[][]> actual = new ArrayList<>();
			long count = new FastNTriplesParser(RDFFormat.NQUADS, () -> false).parse(inputStream,
					(s, p, o, g) -> actual.add(new byte[][] { s, p, o, g }));
			assertEquals(expected.size(), count, "split=" + split);
			for (int statement = 0; statement < expected.size(); statement++) {
				for (int term = 0; term < 4; term++) {
					assertArrayEquals(expected.get(statement)[term], actual.get(statement)[term], "split=" + split);
				}
			}
		}
	}

	private static Stream<DynamicTest> semanticTests(List<ValidCase> cases) {
		return cases.stream()
				.flatMap(c -> Stream.of(Mode.values())
						.map(mode -> DynamicTest.dynamicTest(
								mode + "/" + c.name(), () -> {
									List<byte[][]> actual = parseRaw(c.input().getBytes(UTF_8), mode);
									assertEquals(1, actual.size());
									Value[] expected = { c.expected().getSubject(), c.expected().getPredicate(),
											c.expected().getObject(), c.expected().getContext() };
									for (int i = 0; i < expected.length; i++) {
										assertArrayEquals(
												expected[i] == null ? null : CanonicalTermCodec.encode(expected[i]),
												actual.getFirst()[i], "term=" + i);
										assertEquals(expected[i], actual.getFirst()[i] == null ? null
												: CanonicalTermCodec.decode(actual.getFirst()[i]), "decoded term=" + i);
									}
								})));
	}

	private static Statement quad(Value object) {
		return VF.createStatement(S, P, object, G);
	}

	private static List<byte[][]> parseRaw(byte[] bytes, Mode mode) throws IOException {
		List<byte[][]> terms = new ArrayList<>();
		FastNTriplesParser parser = new FastNTriplesParser(RDFFormat.NQUADS, () -> false);
		FastNTriplesParser.StatementSink sink = (s, p, o, g) -> terms.add(new byte[][] { s, p, o, g });
		long count = mode == Mode.STREAM ? parser.parse(new ByteArrayInputStream(bytes), sink)
				: parser.parseBlock(bytes, 0, bytes.length, 1, sink);
		assertEquals(terms.size(), count);
		return terms;
	}
